    "difficulty": "Intermediate",
    "scope": "Opening page · 16 bars, repeated",
    "universal": true,
    "description": "Opening arrangement in four sections, with the written repeat. A descending bass line connects arpeggiated harmonies.",
    "learning": "Follow the chromatic inner descent A → G♯ → G → F♯. Compare the changing minor/major chord colors without changing A4 = n 0.",
    "source": "Reference: opening page of Stairway to Heaven, music by Jimmy Page and Robert Plant; original transcription credits retained in the score image. Four-line tablature interpreted as high-G ukulele. Sixteen written bars, repeated; articulation and sustain simplified.",
